-- All commercial values below are synthetic test fixtures, rolled back at the end.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.cid(text) returns uuid language sql immutable as $$select md5('credit-engine-'||$1)::uuid$$;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select pg_temp.cid(u),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',u||'@engine.example.test','','{}','{}',now(),now() from unnest(array['owner','other','staff'])u;
insert into organizations(id,name,slug,industry) values(pg_temp.cid('org'),'Engine','credit-engine','salon'),(pg_temp.cid('other-org'),'Other','credit-engine-other','automotive');
insert into organization_memberships(organization_id,user_id,role) values(pg_temp.cid('org'),pg_temp.cid('owner'),'owner'),(pg_temp.cid('org'),pg_temp.cid('staff'),'advisor'),(pg_temp.cid('other-org'),pg_temp.cid('other'),'owner');
insert into branches(id,organization_id,name) values(pg_temp.cid('branch'),pg_temp.cid('org'),'Main');
insert into customers(id,organization_id,full_name) values(pg_temp.cid('customer'),pg_temp.cid('org'),'Synthetic Customer');
insert into notification_outbox(id,organization_id,branch_id,recipient_customer_id,notification_type,channel,recipient_address,template_key,reference_type,reference_id,deduplication_key,status,locked_at,locked_by)
select pg_temp.cid('message-'||n),pg_temp.cid('org'),pg_temp.cid('branch'),pg_temp.cid('customer'),'SYNTHETIC_TEST','sms','+639171234567','synthetic-test','synthetic',pg_temp.cid('ref-'||n),'synthetic-engine-'||n,'processing',now(),'engine-worker' from generate_series(1,6)n;
insert into organization_subscriptions(organization_id,plan_id,provider,status,current_period_start,current_period_end) values(pg_temp.cid('org'),'business','manual','active',now()-interval '2 days',now()+interval '28 days') on conflict(organization_id) do update set plan_id='business',provider='manual',status='active',current_period_start=excluded.current_period_start,current_period_end=excluded.current_period_end;
insert into trial_credit_accounts(organization_id,remaining) values(pg_temp.cid('org'),1);
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'remaining')::integer,1,'exact existing last credit preserved');
select ok((select bool_and(monthly_credits is null) from plans),'production allowance values remain null');
select ok((select bool_and(credit_cost is null and not enabled) from credit_operation_registry where operation_key not in('advanced_report','csv_export')),'unapproved operation costs remain unset and disabled');
select is((select count(*) from credit_operation_registry where operation_key in('advanced_report','csv_export') and credit_cost=1 and enabled and entitlement is null),2::bigint,'only approved report operations have one-credit costs');
set local role service_role;
set local "request.jwt.claims"='{"role":"service_role"}';
select is(reserve_notification_credit(pg_temp.cid('message-1'),'engine-worker')->>'code','CREDIT_NOT_REQUIRED','unconfigured operation does not reserve');
reset role;
select is((select count(*) from organization_credit_reservations),0::bigint,'no reservation for unconfigured operation');
update credit_operation_registry set enabled=true,credit_cost=1 where operation_key='sms_notification';
set local role service_role;
select is(reserve_notification_credit(pg_temp.cid('message-1'),'wrong-worker')->>'code','CLAIM_INACTIVE','invalid worker cannot reserve');
select is(reserve_notification_credit(pg_temp.cid('message-1'),'engine-worker')->>'code','CREDIT_RESERVED','last credit reserved');
select is(reserve_notification_credit(pg_temp.cid('message-1'),'engine-worker')->>'code','CREDIT_RESERVED','same operation retry reserves once');
select is(reserve_notification_credit(pg_temp.cid('message-2'),'engine-worker')->>'code','INSUFFICIENT_CREDITS','second operation cannot overspend');
reset role;
select is((credit_balance_data(pg_temp.cid('org'))->>'remaining')::integer,0,'reservation reduces available balance');
select is((credit_balance_data(pg_temp.cid('org'))->>'reserved')::integer,1,'reserved balance reported');
update notification_outbox set payload='{"changed":true}' where id=pg_temp.cid('message-1');
set local role service_role;
select is(reserve_notification_credit(pg_temp.cid('message-1'),'engine-worker')->>'code','IDEMPOTENCY_CONFLICT','same key with changed payload denied');
reset role;
update notification_outbox set payload='{}' where id=pg_temp.cid('message-1');
set local role service_role;
select is(record_notification_delivery_result(pg_temp.cid('message-1'),'engine-worker','failed','synthetic',null,'PROVIDER_REJECTED'), 'failed','definite rejection recorded');
reset role;
select is((credit_balance_data(pg_temp.cid('org'))->>'remaining')::integer,1,'definite failure releases credit');
select is(settle_notification_credit(pg_temp.cid('message-1'),'released'),'CREDIT_RELEASED','release is idempotent');
set local role service_role;
select is(reserve_notification_credit(pg_temp.cid('message-2'),'engine-worker')->>'code','CREDIT_RESERVED','released credit usable by next operation');
select is(record_notification_delivery_result(pg_temp.cid('message-2'),'engine-worker','sent','synthetic','accepted-test'), 'sent','provider accepted operation committed');
reset role;
select is(settle_notification_credit(pg_temp.cid('message-2'),'committed'),'CREDIT_COMMITTED','duplicate settlement no extra debit');
select is((credit_balance_data(pg_temp.cid('org'))->>'remaining')::integer,0,'accepted operation consumes one credit');
select is((select count(*) from organization_credit_ledger where transaction_type='USAGE'),1::bigint,'one usage transaction');
update credit_operation_registry set credit_cost=null,enabled=false where operation_key='sms_notification';
update notification_outbox set status='processing',locked_at=now(),locked_by='engine-worker' where id=pg_temp.cid('message-2');
set local role service_role;
select is(reserve_notification_credit(pg_temp.cid('message-2'),'engine-worker')->>'code','CREDIT_COMMITTED','unsetting cost cannot replay an already accepted delivery');
reset role;
update credit_operation_registry set credit_cost=1,enabled=true where operation_key='sms_notification';

select is((select count(*) from organization_in_app_notices where kind='EMPTY'),1::bigint,'empty notification deduplicated across retry and recovery');
select is((select count(*) from organization_in_app_notices where recipient_id=pg_temp.cid('staff')),0::bigint,'staff receive no billing notices');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
set local role authenticated;
select is(jsonb_array_length(get_credit_notices(pg_temp.cid('org'))),1,'owner receives current status notice');
select lives_ok($$select read_credit_notice(pg_temp.cid('org'),(get_credit_notices(pg_temp.cid('org'))->0->>'id')::uuid)$$,'owner marks own notice read');
select ok(get_credit_notices(pg_temp.cid('org'))->0->>'readAt' is not null,'read state durable');
select throws_ok($$select ensure_credit_period(pg_temp.cid('org'))$$,'42501',null,'self grant denied');
select throws_ok($$insert into organization_credit_ledger(organization_id,transaction_type,amount,reason_code,idempotency_key) values(pg_temp.cid('org'),'GRANT',100,'forged','forged')$$,'42501',null,'direct ledger grants denied');
select throws_ok($$update credit_operation_registry set credit_cost=0$$,'42501',null,'owner cannot change costs');
select throws_ok($$select reserve_notification_credit(pg_temp.cid('message-3'),'engine-worker')$$,'42501',null,'owner cannot impersonate delivery worker');
select throws_ok($$select get_credit_usage(pg_temp.cid('other-org'))$$,'42501',null,'cross-tenant usage denied');
reset role;
-- Synthetic configured monthly grant; both value AND policy required.
update plans set monthly_credits=10 where id='business';
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'remaining')::integer,0,'value without approved reset policy grants nothing');
update plans set credit_grant_policy='calendar_month_utc' where id='business';
select ensure_credit_period(pg_temp.cid('org'));
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,10,'configured period grants once');
select is((credit_balance_data(pg_temp.cid('org'))->>'oneTimeRemaining')::integer,0,'monthly grant does not refill one-time credits');
select is((select count(*) from organization_credit_grants where credit_class='plan'),1::bigint,'grant replay has one period identity');
set local role authenticated;
select is(jsonb_array_length(get_credit_notices(pg_temp.cid('org'))),0,'old empty notice hidden after recovery');
reset role;
-- Top-up architecture only: synthetic purchased lot, no production top-up flow.
insert into organization_credit_grants(id,organization_id,credit_class,grant_key,allowance) values(pg_temp.cid('purchased'),pg_temp.cid('org'),'purchased','synthetic-topup',5);
insert into organization_credit_ledger(organization_id,grant_id,transaction_type,amount,reason_code,idempotency_key) values(pg_temp.cid('org'),pg_temp.cid('purchased'),'GRANT',5,'synthetic_topup','synthetic-topup');
set local role service_role;
set local "request.jwt.claims"='{"role":"service_role"}';
select is(reserve_notification_credit(pg_temp.cid('message-3'),'engine-worker')->>'code','CREDIT_RESERVED','reserve from configured plan first');
select is(record_notification_delivery_result(pg_temp.cid('message-3'),'engine-worker','retry','synthetic',null,'PROVIDER_TEMPORARY_FAILURE',null,now()+interval '1 minute'),'pending','ambiguous error retried');
reset role;
select is((credit_balance_data(pg_temp.cid('org'))->>'reserved')::integer,1,'ambiguous provider outcome retains reservation');
update notification_outbox set status='processing',locked_at=now(),locked_by='engine-worker' where id=pg_temp.cid('message-3');
set local role service_role;
select is(reserve_notification_credit(pg_temp.cid('message-3'),'engine-worker')->>'code','CREDIT_RESERVED','ambiguous retry reuses reservation');
select is(record_notification_delivery_result(pg_temp.cid('message-3'),'engine-worker','sent','synthetic','test-accepted'),'sent','retry commits original reservation');
reset role;
select is(credit_lot_balance(pg_temp.cid('purchased')),5::bigint,'expiring plan credits spent before purchased');
update plans set monthly_credits=20 where id='business';
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyAllowance')::integer,10,'midcycle allowance change does not grant twice');
update organization_credit_grants set grant_key='previous-synthetic-period',period_start=now()-interval '2 months',period_end=now()-interval '1 month',expires_at=now()-interval '1 month' where credit_class='plan';
select ensure_credit_period(pg_temp.cid('org'));
select is(credit_lot_balance(pg_temp.cid('purchased')),5::bigint,'period rollover never removes purchased credits');
select is((select count(*) from organization_credit_ledger where transaction_type='EXPIRATION'),1::bigint,'unused expired plan balance audited');
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,20,'next period uses newly configured allowance');
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,20,'next period retry does not double grant');
select is(refund_notification_credit(pg_temp.cid('message-2'),'synthetic-refund'),'CREDIT_REFUNDED','verified private refund restores consumed one-time credit');
select is(refund_notification_credit(pg_temp.cid('message-2'),'synthetic-refund-retry'),'CREDIT_REFUNDED','refund retry idempotent even with a different external attempt');
select is((credit_balance_data(pg_temp.cid('org'))->>'oneTimeRemaining')::integer,1,'refund restores only original usage amount');
select is((select count(*) from organization_credit_ledger where transaction_type='REFUND'),1::bigint,'refund has one auditable entry');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('other'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select read_credit_notice(pg_temp.cid('org'),pg_temp.cid('notice'))$$,'42501',null,'cross-tenant notice modification denied');
select throws_ok($$select refund_notification_credit(pg_temp.cid('message-2'),'forged')$$,'42501',null,'self refund denied');
reset role;
set local role anon;
select throws_ok($$select get_credit_usage(pg_temp.cid('org'))$$,'42501',null,'anonymous balance denied');
reset role;
select is(credit_status(20,100),'LOW','20 percent is low');
select is(credit_status(10,100),'CRITICAL','10 percent is critical');
select is(credit_status(0,100),'EMPTY','zero is empty');
select is(credit_status(2,5),'LOW','small absolute threshold');
select is(credit_status(21,100),'NORMAL','above threshold normal');
select * from finish();
rollback;
